rahul: FYI SDK v0.8 changed stream semantics: async iter yields {type:'delta'|'end'|'meta'} instead of plain strings. Also added client.utils.retry helper; we should reference it in TS snippet.

mina: Draft Python (sync-style, simple backoff):
```python
# Python: streaming with retries
import time
from redwood import Client
client = Client(api_key="${RW_KEY}")

def stream_with_backoff(prompt):
    for attempt in range(1, 4):
        try:
            for ev in client.stream_generate(prompt):
                text = getattr(ev, 'delta', getattr(ev, 'text', ''))
                print(text, end='', flush=True)
            return
        except (ConnectionError, TimeoutError):
            time.sleep(min(2 ** attempt, 20))
    raise RuntimeError('stream failed')
```

mina: TS draft (async iterable events + AbortController + small retry):
```ts
// TS: streaming events
import { RedwoodClient } from '@redwood/inference'
const c = new RedwoodClient({ apiKey: process.env.RW_KEY })

async function streamPrompt(p: string) {
  const ac = new AbortController()
  setTimeout(() => ac.abort(), 60_000)
  const it = c.responses.stream({ prompt: p }, { signal: ac.signal })
  for await (const e of it) {
    if (e.type === 'delta') process.stdout.write(e.delta)
    if (e.type === 'end') console.log('\n--done--')
  }
}

// optional: use client.utils.retry(fn) in caller
```

mina: Go pagination example (context-aware):
```go
// Go: page loop with context cancellation
ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
defer cancel()
page := ""
for {
  resp, err := client.ListEmbeddings(ctx, &ListRequest{PageToken: page, PageSize: 200})
  if err != nil { return err }
  for _, it := range resp.Items { fmt.Println(it.Id) }
  if resp.NextPageToken == "" { break }
  page = resp.NextPageToken
}
```

